<main class="shell">
<nav class="top" aria-label="Gallery"><a href="index.php">Chloe Reads Jon</a><span>A tiny game about better tests</span></nav>
<header>
<h1>Coverage Critters</h1>
<p class="intro">The parcels are piling up. Help the depot crew test every sorting route, then catch the bug hiding behind a perfect score.</p>
<figure><img src="data:image/webp;base64," width="1536" height="1024" alt="A fox sorts parcels through a three-belt depot while a raccoon inspects a suspicious delivery."><figcaption>Fox runs the belts. Raccoon trusts the results a little less. A healthy working relationship.</figcaption></figure>
</header>
<noscript><p>This game needs JavaScript to run the sorting rules. Enable it, then reload the page.</p></noscript>
<div id="game">
<div class="shiftbar" aria-label="Your shifts"><span id="tab0" aria-current="step">1. Two belts</span><span id="tab1">2. Handle with care</span><span id="tab2">3. The mystery</span></div>
<div class="work">
<section aria-labelledby="shiftTitle">
<h2 id="shiftTitle" tabindex="-1">Two belts. One small test suite.</h2>
<p class="brief" id="brief">Send different weights until both the light and heavy belt have been used. Can you do it in two parcels?</p>
<form id="parcel">
<fieldset id="weightfield"><legend>Pack a test parcel</legend>
<label class="weightrow" for="weight"><span>Parcel weight</span><output id="weightOut" for="weight">2 kg</output></label>
<input id="weight" type="range" min="1" max="9" value="2" step="1">
</fieldset>
<fieldset id="flags" hidden><legend>Choose its handling</legend>
<label class="check"><input type="checkbox" id="express">Express delivery</label>
<label class="check"><input type="checkbox" id="fragile">Fragile contents</label>
</fieldset>
<p class="rule" id="rule"><strong>The promise:</strong> Only parcels above 5 kg belong on the heavy belt.</p>
<div class="controls"><button class="primary" type="submit" id="send">Send test parcel</button><button type="button" id="hint">A small hint</button></div>
<p id="hinttext" hidden></p>
</form>
<p id="feedback" role="status" aria-live="polite">No routes tested yet. Send your first parcel.</p>
<button id="advance" hidden>Next shift</button>
</section>
<section class="sheet" aria-labelledby="sheetTitle">
<div class="sheethead"><h3 id="sheetTitle">The routing sheet</h3><span id="coverage">0 / 2 routes</span></div>
<pre class="code" id="code" aria-label="Sorting code"></pre>
<div id="routes" class="routes" aria-label="Tested routes"></div>
<div class="result" aria-live="polite" aria-atomic="true"><p id="receipt">Awaiting your first parcel.</p><p id="detail">Every send runs the code. The green lines show the instructions it actually used.</p></div>
</section>
</div>
<section class="ledger" aria-labelledby="ledgerTitle"><h3 id="ledgerTitle">Dispatch ledger</h3><p id="ledgerNote">Your test suite is the set of parcels you send. Repeat parcels are allowed; new routes are more useful.</p><ol id="log"><li class="empty">No parcels on this shift yet.</li></ol></section>
</div>
<section id="finished" hidden tabindex="-1" aria-labelledby="finishTitle"><h2 id="finishTitle">Depot open. Mystery solved.</h2><p id="finaltext"></p><p>You covered the routes, challenged the promise, and reran the tests after the fix. Raccoon approves. Fox would like lunch.</p><button id="replay">Run the depot again</button></section>
<section class="lesson" aria-label="What the game teaches">
<div><h3>What does coverage tell us?</h3><p>Branch coverage asks whether a test suite has taken both outcomes of each decision. In these small early-return functions, covering every destination covers every decision outcome too.</p><p>It tells you where tests went. It cannot tell you whether the answer was right.</p></div>
<div><h3>A tiny idea from 2004</h3><p>Jon bookmarked EMMA, a free Java coverage tool. This depot is a playful, simplified cousin: choose test inputs, see what runs, then check the result against a promise.</p><p>No Java required. No actual parcels harmed.</p></div>
</section>
<footer><p>Inspired by Jon's <a href="?inspiration=1">EMMA: a free Java code coverage tool</a>.</p><p>Fictional sorting rules, real JavaScript execution. Original GPT Image illustration. <a href="index.php">Explore the rest of the lab</a>.</p></footer>
</main>
<script>
'use strict';
const $=id=>document.getElementById(id);
const stages=[
 {title:'Two belts. One small test suite.',brief:'Send different weights until both the light and heavy belt have been used. Can you do it in two parcels?',rule:'Only parcels above 5 kg belong on the heavy belt.',routes:['Light belt','Heavy belt'],hint:'One parcel at 2 kg and another at 8 kg will take opposite paths.'},
 {title:'Which instruction comes first?',brief:'Express parcels jump the queue. Fragile parcels need padding, unless express delivery takes priority. Reach all three destinations.',rule:'Express first. Otherwise, pad fragile parcels. Everything else goes standard.',routes:['Express belt','Padded belt','Standard belt'],hint:'Try express, then fragile without express, then neither. Both boxes checked still takes the express route.'},
 {title:'A perfect score. A suspicious parcel.',brief:'The new sorter has a mistake. Cover both routes, then find a parcel that breaks the promise. A perfect coverage score is not enough.',rule:'Only parcels above 5 kg belong on the heavy belt. Exactly 5 kg must stay light.',routes:['Light belt','Heavy belt'],hint:'Try a parcel below 5 kg, one above it, and exactly 5 kg. A boundary is an excellent place for a bug.'}
];
let stage=0,seen=new Set(),tests=[],total=0,found=false,patched=false,shiftCounts=[];
function lines(){
 if(stage===1)return ['if (express) {','  return "Express belt";','}','if (fragile) {','  return "Padded belt";','}','return "Standard belt";'];
 return ['if (kg '+(stage===2&&!patched?'>=':'>')+' 5) {','  return "Heavy belt";','}','return "Light belt";'];
}
function execute(kg,express,fragile){
 if(stage===1){
  if(express)return {route:0,trace:[0,1],expected:0};
  if(fragile)return {route:1,trace:[0,3,4],expected:1};
  return {route:2,trace:[0,3,6],expected:2};
 }
 const heavy=stage===2&&!patched?kg>=5:kg>5;
 return {route:heavy?1:0,trace:heavy?[0,1]:[0,3],expected:kg>5?1:0};
}
function renderCode(trace=[]){
 $('code').replaceChildren(...lines().map((text,i)=>{
  const line=document.createElement('span');line.className='codeline'+(trace.includes(i)?' executed':'');line.textContent=text;return line;
 }));
}
function renderRoutes(now=-1){
 const s=stages[stage];$('coverage').textContent=seen.size+' / '+s.routes.length+' routes';
 $('routes').replaceChildren(...s.routes.map((text,i)=>{
  const el=document.createElement('span');el.className='route'+(seen.has(i)?' hit':'')+(now===i?' now':'');el.textContent=text+' · '+(seen.has(i)?'tested':'untested');return el;
 }));
}
function startShift(focus=true){
 seen=new Set();tests=[];found=false;patched=false;
 const s=stages[stage];$('shiftTitle').textContent=s.title;$('brief').textContent=s.brief;
 $('rule').replaceChildren();const strong=document.createElement('strong');strong.textContent='The promise: ';$('rule').append(strong,document.createTextNode(s.rule));
 $('weightfield').hidden=stage===1;$('flags').hidden=stage!==1;
 $('weight').value=2;$('weightOut').textContent='2 kg';$('express').checked=false;$('fragile').checked=false;
 $('hinttext').hidden=true;$('advance').hidden=true;$('send').disabled=false;
 $('receipt').textContent='Awaiting your first parcel.';$('detail').textContent='Every send runs the code. The green lines show the instructions it actually used.';
 $('feedback').textContent='No routes tested yet. Send your first parcel.';
 $('log').replaceChildren();const li=document.createElement('li');li.className='empty';li.textContent='No parcels on this shift yet.';$('log').append(li);
 for(let i=0;i<3;i++){if(i===stage)$('tab'+i).setAttribute('aria-current','step');else $('tab'+i).removeAttribute('aria-current');}
 renderCode();renderRoutes();if(focus)$('shiftTitle').focus();
}
$('weight').addEventListener('input',()=>{$('weightOut').textContent=$('weight').value+' kg';});
$('hint').addEventListener('click',()=>{$('hinttext').textContent=stages[stage].hint;$('hinttext').hidden=false;});
$('parcel').addEventListener('submit',event=>{
 event.preventDefault();
 const kg=Number($('weight').value),express=$('express').checked,fragile=$('fragile').checked;
 const result=execute(kg,express,fragile),name=stages[stage].routes[result.route],bad=result.route!==result.expected;
 const fresh=!seen.has(result.route);seen.add(result.route);total++;
 tests.push({kg,express,fragile});if(bad)found=true;
 renderCode(result.trace);renderRoutes(result.route);
 $('receipt').textContent=bad?'Mismatch caught: '+kg+' kg went heavy.':'Delivered to the '+name.toLowerCase()+'.';
 $('detail').textContent=bad?'Expected: Light belt. Actual: Heavy belt. The code uses >=, but the promise says above 5.':fresh?'New route covered. This parcel added a useful test.':'This route was already tested. Try a different input to reach a new one.';
 const description=stage===1?((express?'Express':'Regular')+', '+(fragile?'fragile':'not fragile')):kg+' kg';
 const li=document.createElement('li');if(bad)li.className='fault';const left=document.createElement('span'),right=document.createElement('span');left.textContent='#'+tests.length+' · '+description;right.textContent=name+(bad?' · mismatch':' · matches');li.append(left,right);
 if(tests.length===1)$('log').replaceChildren();$('log').prepend(li);
 $('receipt').classList.remove('stamping');void $('receipt').offsetWidth;$('receipt').classList.add('stamping');
 const complete=seen.size===stages[stage].routes.length;
 if(stage<2&&complete){$('feedback').textContent='Every route tested in '+tests.length+' parcels. Ready for the next shift.';$('advance').textContent=stage===0?'Next: handle with care':'Next: the five-kilo mystery';$('advance').hidden=false;}
 else if(stage===2&&complete&&found){$('feedback').textContent='Both routes covered and the boundary bug caught. Repair the rule, then rerun your suite.';$('advance').textContent='Repair rule & rerun tests';$('advance').hidden=false;}
 else if(stage===2&&complete){$('feedback').textContent='100% route coverage. But the sorter still has a bug. Which weight breaks the promise?';}
 else $('feedback').textContent=bad?'Good catch. Now test the missing route before the repair.':seen.size+' of '+stages[stage].routes.length+' routes covered. Keep exploring.';
});
$('advance').addEventListener('click',()=>{
 if(stage<2){shiftCounts.push(tests.length);stage++;startShift();return;}
 patched=true;const failures=tests.filter(t=>{const r=execute(t.kg,t.express,t.fragile);return r.route!==r.expected;}).length;
 if(failures){$('feedback').textContent='Some tests still fail. Keep investigating.';return;}
 $('game').hidden=true;$('finished').hidden=false;
 $('finaltext').textContent='All '+tests.length+' tests from the mystery shift now pass, including the 5 kg parcel. You sent '+total+' parcels across all three shifts. The fixed rule is kg > 5.';
 $('finished').focus();
});
$('replay').addEventListener('click',()=>{stage=0;total=0;shiftCounts=[];$('finished').hidden=true;$('game').hidden=false;startShift();});
startShift(false);
</script>
